    let receivedError: Error | undefined;
    const hooks: OrchestratorHooks = {
      onError: async (_session, error) => {
        receivedError = error;
      },
    };

    const orchestrator = createChatOrchestrator(
      createErrorProvider('non-error boom'),
      promptBuilder,
      undefined,
      {hooks}
    );
    const outcome = await orchestrator.processMessage(createSession('hello')).then(
