      (thrown: unknown) => thrown
    );

    expect({
      outcome,
      isError: receivedError instanceof Error,
      message: receivedError?.message,
      cause: receivedError?.cause,
    }).toEqual({
      outcome: 'non-error boom',
      isError: true,
      message: 'non-error boom',
      cause: 'non-error boom',
    });
  });
});

